/** Narrow real inventory/coins/skills; normal NPC partial sale, paid route, physical walking and earned combat XP. */
public class TownHuntFundingVerify extends NoviceTravelTopupVerify {
 static Map<Integer,Integer> counts(Player p){Map<Integer,Integer> r=new HashMap<>();for(ItemInstance i:p.getInventory().getItems())r.put(i.getObjectId(),i.getCount());return r;}
 static Object newLife(Autobot b)throws Exception{Object l=Class.forName("dev.l2j.autobots.population.LifeBehavior").getConstructor(Autobot.class).newInstance(b);invoke(b,"setLife",l);member(l,"tripDoneInTown").set(l,true);return l;}
 @SuppressWarnings("unchecked") public static void main(String[] args){try{
  if(!"yes".equals(System.getenv("L2_MOVEMENT_ISOLATED")))throw new IllegalStateException();GameServer.main(new String[0]);Object fm=singleton("offlinelife.OfflineFarmManager"),mgr=singleton("AutobotsManager");invoke(member(fm,"travelTask").get(fm),"cancel");invoke(member(AutofarmManager.INSTANCE,"onUpdateTask").get(AutofarmManager.INSTANCE),"cancel");gear=singleton("population.economy.Gear");market=singleton("population.economy.Market");Autobot b=(Autobot)invoke(singleton("dao.AutobotsDao"),"loadByName","4ertonish");check(b!=null&&b.getLevel()==13&&b.getExp()==148994&&b.getAdena()==563,"narrow snapshot restores actual stalled actor without changing resources");b.setAccessLevel(0);b.setIsInvul(false);suspendValue(mgr,"spawnAutobot",b);((Map<?,?>)invoke(mgr,"getActiveBots")).remove(b.getName());invoke(b,"cancelSequence");Thread.sleep(300);b.stopMove(null);b.setAccessLevel(0);b.setIsInvul(false);Object life=newLife(b);check((Integer)invoke(singleton("population.economy.Healing"),"count",b)==10&&b.getInventory().getInventoryItemCount(736,-1)==1,"actual carried heals and own escape scroll are preserved");
  boolean readiness=Arrays.asList(args).contains("--readiness");if(readiness){check((Boolean)invoke(gear,"isWeak",b),"the actual starter wand is recognized as underpowered despite its legal No Grade");Object fitness=member(life,"fitness").get(life);invoke(fitness,"update");check(invoke(fitness,"getMode").toString().equals("Farm"),"ordinary fitness lowers difficulty before another fatal pull");kotlin.ranges.IntRange range=(kotlin.ranges.IntRange)invoke(singleton("population.HuntingSpots"),"targetLevels",b);check(range.getLast()<=10,"anchors and combat honor the real weapon's safer prey range");if(Arrays.asList(args).contains("--plan-only")){System.out.println("NOVICE WEAPON READINESS PLAN ALL PASSED");System.exit(0);}}
  Map<Integer,Integer> before=counts(b);List<ItemInstance> eligible=(List<ItemInstance>)invoke(gear,"surplus",b);Set<Integer> allowed=new HashSet<>();for(ItemInstance i:eligible)if(i.isSellable())allowed.add(i.getObjectId());int wallet=b.getAdena();long xp=b.getExp(),began=System.currentTimeMillis();await(life,"hunt");int earned=b.getAdena()-wallet;check(earned>0||readiness&&earned==0,"ordinary hunt sells its own unprotected surplus to fund a complete safe exit");check(b.getExp()==xp,"selling resources neither grants nor fakes combat experience");
  int value=0,changed=0;for(Map.Entry<Integer,Integer> e:before.entrySet()){ItemInstance item=b.getInventory().getItemByObjectId(e.getKey());int left=item==null?0:item.getCount(),sold=e.getValue()-left;if(sold>0){check(allowed.contains(e.getKey()),"only originally unprotected surplus is sold");ItemInstance old=eligible.stream().filter(i->i.getObjectId()==e.getKey()).findFirst().orElseThrow();value+=(old.getReferencePrice()/2)*sold;changed+=sold;}}check(value==earned&&b.getInventory().getInventoryItemCount(1060,-1)==10&&b.getInventory().getInventoryItemCount(736,-1)==1,"NPC revenue exactly matches removed surplus; healing and escape resources stay owned");
  if(Arrays.asList(args).contains("--plan-only")){System.out.println("TOWN HUNT FUNDING PLAN ALL PASSED");System.exit(0);}
  if(earned>0)check((Long)member(life,"nextFundingRetryAt").get(life)>System.currentTimeMillis(),"funding action has a bounded retry delay");if(!Arrays.asList(args).contains("--policy-only")){int readyCash=b.getAdena();List<?> offers=(List<?>)invoke(singleton("population.economy.GatekeeperTravel"),"offers",b);boolean paidRide=false;long deadline=System.currentTimeMillis()+480000,report=System.currentTimeMillis();while(!b.isDead()&&b.getExp()<=xp&&System.currentTimeMillis()<deadline){if(Boolean.TRUE.equals(invokeStaticUnderAttack(b)))await(invoke(b,"getCombatBehavior"),"onUpdate");else await(life,"hunt");if(!paidRide)for(Object offer:offers)if(readyCash-b.getAdena()==(Integer)invoke(offer,"getPrice")&&gap(location(b),(net.sf.l2j.gameserver.model.location.Location)invoke(offer,"getExit"))<=200)paidRide=true;if(System.currentTimeMillis()-report>=20000){report=System.currentTimeMillis();System.out.println("TOWN FUNDING INFO seconds="+(report-began)/1000+" at="+location(b)+" cash="+b.getAdena()+" xp="+b.getExp()+" hp="+(int)b.getCurrentHp());}Thread.sleep(350);}check((paidRide||readiness&&earned==0)&&!b.isDead()&&b.getExp()>xp,"actual formerly idle actor pays a real ride, walks to prey and earns normal experience");check(b.getInventory().getInventoryItemCount(736,-1)==1&&!b.isGM()&&!b.isInvul(),"funded recovery uses no GM or invulnerability");System.out.println("TOWN FUNDING RESULT xp="+xp+"->"+b.getExp()+" sale="+earned+" soldUnits="+changed+" cash="+b.getAdena()+" seconds="+(System.currentTimeMillis()-began)/1000);if(readiness){check(b.getActiveWeaponItem().getItemId()==6,"real recovery retains the actual original wand through earned combat progress");ItemInstance staff=b.getInventory().addItem("Controlled post-combat weapon policy",177,1,b,null);invoke(gear,"equip",b,staff);check(!(Boolean)invoke(gear,"isWeak",b),"a materially stronger legal No Grade weapon is not incorrectly penalized");ItemInstance graded=b.getInventory().addItem("Controlled post-combat grade enchant policy",185,1,b,null);Object equipment=singleton("offlinelife.OfflineEquipment");double base=(Double)invoke(equipment,"score",b,graded);graded.setEnchantLevel(3);check((Double)invoke(equipment,"score",b,graded)>base,"core-legal grade enchant stats count toward weapon readiness");}}b.deleteMe();
  Autobot c=new Autobot(IdFactory.getInstance().getNextId(),PlayerData.getInstance().getTemplate(ClassId.HUMAN_FIGHTER),new Appearance((byte)0,(byte)0,(byte)0,Sex.MALE));c.setName("TownFundingGuards");c.setAccessLevel(0);c.setXYZ(npc("Jasmine").getX()+40,npc("Jasmine").getY()+40,npc("Jasmine").getZ());c.getStat().setLevel((byte)13);c.getStat().setExp(Experience.LEVEL[13]);suspendValue(mgr,"spawnAutobot",c);((Map<?,?>)invoke(mgr,"getActiveBots")).remove(c.getName());invoke(c,"cancelSequence");Thread.sleep(300);c.stopMove(null);Object funding=singleton("population.economy.HuntFunding");if(readiness){c.getStat().setLevel((byte)9);check(!(Boolean)invoke(gear,"isWeak",c),"early novice policy remains unchanged below level 10");c.getStat().setLevel((byte)13);check((Boolean)invoke(gear,"isWeak",c),"an unarmed older novice is not treated as battle ready");}supplies(c,10);money(c,563);check(invoke(funding,"plan",c,Collections.emptySet())==null,"no owned surplus means no invented sale proceeds");c.getInventory().addItem("Controlled surplus fixture",1870,20,c,null);supplies(c,2);check(invoke(funding,"plan",c,Collections.emptySet())==null,"insufficient carried healing does not trigger risky funding");supplies(c,10);erase(c,736);check(invoke(funding,"plan",c,Collections.emptySet())==null,"missing owned escape scroll also prevents liquidation");supplies(c,10);money(c,1000000);check(invoke(funding,"plan",c,Collections.emptySet())==null,"an already funded character does not liquidate surplus");money(c,563);Object plan=invoke(funding,"plan",c,Collections.emptySet());check(plan!=null,"controlled funded-surplus plan is available");Object seq=Class.forName("dev.l2j.autobots.population.economy.HuntFunding$SaleSequence").getConstructor(Autobot.class,Class.forName("dev.l2j.autobots.population.economy.HuntFunding$Plan"),Set.class).newInstance(c,plan,Collections.emptySet());Player owner=Player.restore(268486152);invoke(c,"setController",owner);int cash=c.getAdena(),coal=c.getInventory().getInventoryItemCount(1870,-1);await(seq,"execute");check(c.getAdena()==cash&&c.getInventory().getInventoryItemCount(1870,-1)==coal,"manual control handoff prevents an autonomous NPC sale");invoke(c,"setController",(Object)null);await(seq,"execute");int received=c.getAdena()-cash,removed=coal-c.getInventory().getInventoryItemCount(1870,-1);check(received>0&&received==removed*100,"after valid handoff back, an actual partial NPC sale still pays exactly for owned surplus");System.out.println(readiness?"NOVICE WEAPON READINESS ALL PASSED":Arrays.asList(args).contains("--policy-only")?"TOWN HUNT FUNDING POLICY ALL PASSED":"TOWN HUNT FUNDING ALL PASSED");System.exit(0);
 }catch(Throwable t){t.printStackTrace();System.exit(1);}}
}
